package io.github.kotlinmania.opus

/**
 * An error generated by the Opus library.
 */
public class OpusError internal constructor(
    private val functionName: String,
    private val errorCode: ErrorCode,
) : Exception("$functionName: ${errorCode.errorDescription()}") {
    /** Get the name of the Opus function from which the error originated. */
    public fun function(): String = functionName

    /** Get a textual description of the error provided by Opus. */
    public fun description(): String = errorCode.errorDescription()

    /** Get the Opus error code of the error. */
    public fun code(): ErrorCode = errorCode

    override fun equals(other: Any?): Boolean =
        other is OpusError &&
            functionName == other.functionName &&
            errorCode == other.errorCode

    override fun hashCode(): Int = 31 * functionName.hashCode() + errorCode.hashCode()

    override fun toString(): String = "$functionName: ${errorCode.errorDescription()}"

    internal companion object {
        fun badArg(what: String): OpusError = OpusError(functionName = what, errorCode = ErrorCode.BadArg)

        fun fromCode(
            what: String,
            code: Int,
        ): OpusError = OpusError(functionName = what, errorCode = ErrorCode.fromInt(code))
    }
}

internal fun checkLen(value: Int): Int {
    if (value < 0) {
        throw IllegalArgumentException("length out of range: $value")
    }
    return value
}
